tests:
const greet = (greeting, name) => `${greeting}, ${name}!`;
test({ sr: 'prvi argument je unapred zadat', en: 'the first argument is preset' }, () => {
  const hello = partial(greet, 'Hello');
  expect(hello('Ana')).toBe('Hello, Ana!');
});
test({ sr: 'zadati argumenti idu pre novih', en: 'preset arguments go before the new ones' }, () => {
  const sub = (a, b, c) => a - b - c;
  expect(partial(sub, 10, 3)(2)).toBe(5);
});
test({ sr: 'može da se poziva više puta', en: 'can be called many times' }, () => {
  const hello = partial(greet, 'Hi');
  expect(hello('Ana')).toBe('Hi, Ana!');
  expect(hello('Marko')).toBe('Hi, Marko!');
});

hiddenTests:
test('without preset arguments it behaves like fn', () => {
  const add3 = (a, b, c) => a + b + c;
  expect(partial(add3)(1, 2, 3)).toBe(6);
});
test('partial does not call fn by itself', () => {
  let calls = 0;
  const fn = () => { calls++; };
  const p = partial(fn, 1);
  expect(calls).toBe(0);
  p();
  expect(calls).toBe(1);
});
test('the preset arguments are not changed between calls', () => {
  const seen = [];
  const p = partial((...all) => { seen.push(all.length); return all; }, 1, 2);
  p(3);
  p(4, 5);
  p();
  expect(seen).toEqual([3, 4, 2]);
  expect(p(9)).toEqual([1, 2, 9]);
});
test('several preset and several new arguments keep their order', () => {
  const list = (...all) => all;
  expect(partial(list, 1, 2)(3, 4)).toEqual([1, 2, 3, 4]);
});
test('two partial functions from the same fn are independent', () => {
  const a = partial(greet, 'A');
  const b = partial(greet, 'B');
  expect(a('x')).toBe('A, x!');
  expect(b('x')).toBe('B, x!');
});
